<script setup lang="ts">
import {computed,watch,ref,onMounted,onUnmounted} from 'vue';import {useRouter,useRoute} from 'vue-router';import {useAuthStore} from '../stores/auth';import {request} from '../api/http';import {endpoints} from '../api/endpoints';import {pages} from '../router/navigation';
const auth=useAuthStore(),router=useRouter(),route=useRoute(),opened=ref(false),clock=ref(new Date().toLocaleString());const links=computed(()=>pages.filter(x=>auth.permissions.includes(x.permission))),title=computed(()=>pages.find(x=>x.path===route.path)?.label||'数据治理中心');let timer:ReturnType<typeof setInterval>;
onMounted(()=>timer=setInterval(()=>clock.value=new Date().toLocaleString(),1000));onUnmounted(()=>clearInterval(timer));watch(()=>route.path,()=>opened.value=false);watch(()=>auth.token,x=>{if(!x)router.replace('/login')});async function logout(){try{await request(endpoints['D18-API-002'])}finally{auth.clear();router.replace('/login')}}
</script>
<template><div v-if="route.path==='/login'" class="login-shell"><RouterView/></div><div v-else class="shell"><aside :class="{opened}"><div class="brand"><span class="brand-symbol">◈</span><div><h1>数据治理中心</h1><small>DATA GOVERNANCE</small></div></div><div class="nav-caption">治理工作空间</div><nav><RouterLink v-for="(page,i) in links" :key="page.path" :to="page.path"><span class="nav-number">{{String(i+1).padStart(2,'0')}}</span>{{page.label}}</RouterLink></nav><div class="sidebar-user" v-if="auth.user"><span class="avatar">{{auth.user.displayName.slice(0,1)}}</span><div>{{auth.user.displayName}}<small>{{auth.user.roleCodes.join(' · ')}}</small></div><button @click="logout" title="退出登录">退出</button></div></aside><div class="main-shell"><header class="topbar"><div class="actions"><button class="mobile-menu" @click="opened=!opened" aria-label="切换导航">☰</button><span class="system-tag">统一治理平台</span><b>{{title}}</b></div><time>{{clock}}</time></header><main><RouterView/></main><footer>企业数据资产治理与数据质量闭环管理系统</footer></div></div></template>
